import{_ as e,o as d,c as o,ag as c}from"./chunks/framework.DQe9aj1R.js";const g=JSON.parse('{"title":"以前の書き方から移る","description":"","frontmatter":{},"headers":[],"relativePath":"guide/compatibility.md","filePath":"guide/compatibility.md","lastUpdated":1789803897000}'),r={name:"guide/compatibility.md"};function a(i,t,n,l,h,s){return d(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="以前の書き方から移る" tabindex="-1">以前の書き方から移る <a class="header-anchor" href="#以前の書き方から移る" aria-label="Permalink to &quot;以前の書き方から移る&quot;">​</a></h1><p>v8 では、よく使う入力・描画・位置情報の入口を足し、廃止予定だった宣言と旧い位置情報の入口を削除しました。新しい課題は、削除した名前に戻さないでください。</p><p>機械生成のAPIページは、ソースより遅れていることがあります。移したあとの正しさは <code>Runtime/Scripts</code> で確認します。</p><h2 id="ポインター" tabindex="-1">ポインター <a class="header-anchor" href="#ポインター" aria-label="Permalink to &quot;ポインター&quot;">​</a></h2><p>1本の指やマウスは <code>gc.Pointer</code>、複数は <code>gc.Pointers</code> です。イベントの発生順が要るときだけ <code>gc.PointerEvents</code> を使います。</p><table tabindex="0"><thead><tr><th>以前</th><th>今</th></tr></thead><tbody><tr><td><code>LastPointerX</code> / <code>LastPointerY</code></td><td><code>gc.Pointer.X</code> / <code>gc.Pointer.Y</code></td></tr><tr><td><code>IsTouchBegan()</code></td><td><code>gc.Pointer.Down</code></td></tr><tr><td><code>IsTouched()</code></td><td>そのフレームに接触があるか。<code>Down</code> / <code>Held</code> / <code>Up</code> を見る</td></tr><tr><td><code>IsTouchEnded()</code></td><td><code>gc.Pointer.Up</code></td></tr><tr><td><code>TryGetPointerEventAll</code> から始める導入</td><td><code>gc.Pointers</code>。順序が要るときだけ <code>gc.PointerEvents</code></td></tr><tr><td><code>GetPointerX(i)</code></td><td><code>gc.Pointers[i].X</code></td></tr><tr><td>中断が <code>End</code> に混ざる</td><td><code>Cancelled</code>。タップや普通の解放には数えない</td></tr><tr><td>代表の指を離すと、残った指へ引き継ぐ</td><td>引き継がない。残った指は一覧で追う</td></tr></tbody></table><p><code>LastPointerX</code> と <code>IsTouchBegan</code> はまだ残っていますが、最後に届いたイベントの位置であり、今つかんでいる指とは限りません。複数指のドラッグには使いません。</p><p><code>PointerCount</code> はイベント数です。今ある指の本数ではありません。今の本数は <code>gc.Pointers.Count</code> です。押している本数なら、<code>Held</code> が真の要素を数えます。</p><p>同じ対象を、状態の一覧とイベント列の両方で動かすと二重に処理されます。どちらか一方にします。</p><h2 id="位置情報" tabindex="-1">位置情報 <a class="header-anchor" href="#位置情報" aria-label="Permalink to &quot;位置情報&quot;">​</a></h2><p>旧い位置情報の入口は削除しました。<code>GcGeolocationEvent</code>、<code>StartGeolocationService</code>、<code>StopGeolocationService</code>、<code>TryGetGeolocationEvent</code>、<code>GeolocationStatus</code>、<code>HasUserAuthorizedPermissionGeolocation</code> はありません。</p><table tabindex="0"><thead><tr><th>以前</th><th>今</th></tr></thead><tbody><tr><td><code>StartGeolocationService</code></td><td><code>gc.Location.Start()</code></td></tr><tr><td><code>StopGeolocationService</code></td><td><code>gc.Location.Stop()</code></td></tr><tr><td><code>TryGetGeolocationEvent</code></td><td><code>gc.Location.TryGetSample</code></td></tr><tr><td><code>GeolocationStatus</code></td><td><code>gc.Location.Status</code></td></tr><tr><td>権限要求と起動を別々に書く導入</td><td><code>Start</code> が許可の確認から入る</td></tr></tbody></table><p>値の有無は <code>TryGetSample</code> で一度に判断します。Editor では未対応です。緯度経度は <code>double</code> です。Editor 用の固定座標を、測位の成功として出さないでください。</p><h2 id="画像と文字" tabindex="-1">画像と文字 <a class="header-anchor" href="#画像と文字" aria-label="Permalink to &quot;画像と文字&quot;">​</a></h2><table tabindex="0"><thead><tr><th>以前</th><th>今</th></tr></thead><tbody><tr><td><code>TryGetImage</code> してから <code>DrawImage</code></td><td><code>gc.DrawImage(&quot;BlueSky.png&quot;, x, y)</code></td></tr><tr><td><code>SetStringAnchor</code> のあと <code>DrawString</code></td><td><code>gc.DrawString(text, x, y, anchor: GcAnchor.UpperRight)</code></td></tr><tr><td><code>SetRectAnchor</code> を画像にも引き継ぐ</td><td>位置指定の <code>DrawImage</code> / <code>DrawString</code> は呼び出しの <code>anchor</code> だけを見る</td></tr><tr><td><code>DrawRightString</code> / <code>DrawCenterString</code></td><td><code>DrawString(..., anchor: ...)</code></td></tr><tr><td><code>SetColor</code> の float と byte の取り違え</td><td><code>SetColor(int, int, int, int = 255)</code>。0 から 255。範囲外は丸める</td></tr><tr><td>0 から 1 の色</td><td><code>GcColor.FromNormalized</code>。NaN は不可</td></tr><tr><td><code>DrawCameraImage</code> が止まっているカメラを再生する</td><td>既定は再生しない。先に <code>PlayCameraImage</code>。従来の連携だけ <code>autoPlay: true</code></td></tr></tbody></table><p>図形の <code>FillRect</code> や、位置を省略した <code>DrawImage(image)</code> / <code>DrawString(text)</code> は、これまでどおり <code>SetRectAnchor</code> / <code>SetStringAnchor</code> を使います。任意の画像の有無で分岐するときや、同じハンドルを繰り返すときだけ <code>TryGetImage</code> を使います。</p><h2 id="アクター" tabindex="-1">アクター <a class="header-anchor" href="#アクター" aria-label="Permalink to &quot;アクター&quot;">​</a></h2><table tabindex="0"><thead><tr><th>以前</th><th>今</th></tr></thead><tbody><tr><td><code>GetActorList&lt;T&gt;</code> が返した <code>ReadOnlyActorList&lt;T&gt;</code></td><td><code>TryGetActorAll&lt;T&gt;</code></td></tr></tbody></table><p><code>GetActorList</code> と <code>ReadOnlyActorList&lt;T&gt;</code> はありません。</p><h2 id="キーボード" tabindex="-1">キーボード <a class="header-anchor" href="#キーボード" aria-label="Permalink to &quot;キーボード&quot;">​</a></h2><table tabindex="0"><thead><tr><th>以前</th><th>今</th></tr></thead><tbody><tr><td><code>IsKeyDown(Key.Space)</code></td><td><code>gc.Key(GcKey.Space).Down</code></td></tr><tr><td><code>IsKeyPress(Key.Space)</code></td><td><code>gc.Key(GcKey.Space).Held</code></td></tr><tr><td><code>IsKeyUp(Key.Space)</code></td><td><code>gc.Key(GcKey.Space).Up</code></td></tr><tr><td><code>KeyCode</code> や文字1つを渡す引数</td><td>削除済み。<code>GcKey</code> を使う</td></tr></tbody></table><p><code>UnityEngine.InputSystem.Key</code> を渡す <code>IsKeyDown</code> は残っています。新しい課題は <code>gc.Key</code> で書いてください。</p>',22)])])}const y=e(r,[["render",a]]);export{g as __pageData,y as default};
